solution_code:
#include <iostream>

class Vec2 {
    int m_x;
    int m_y;
public:
    constexpr Vec2(int x, int y) : m_x{x}, m_y{y} {}
    constexpr int dot(Vec2 other) const { return m_x * other.m_x + m_y * other.m_y; }
};

static_assert(Vec2{1, 2}.dot(Vec2{3, 4}) == 11, "dot of (1,2)-(3,4) must be 11");

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int x1, y1, x2, y2;
        std::cin >> x1 >> y1 >> x2 >> y2;
        Vec2 a{x1, y1};
        Vec2 b{x2, y2};
        std::cout << "dot=" << a.dot(b) << "\n";
    }
}
